#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-09-06

# Gate: scripts/eval/static-analysis.sh:568 (exit 0 iff FAIL_COUNT == 0); npm run eval:static
# Writes tests/evals/results/static-analysis.json, so BOTH arms run in a fixture root.
set -uo pipefail
H="${H:?set by the fault-arms runner}"
REPO="${REPO:?set by the fault-arms runner}"
G="$REPO/scripts/eval/static-analysis.sh"
F="$H/fixtures/eval-static"; rm -rf "$F"; mkdir -p "$F/root/src" "$F/root/tests"

cp -R "$REPO/src/skills" "$F/root/src/skills"
cp -R "$REPO/src/agents" "$F/root/src/agents"
cp -R "$REPO/tests/evals" "$F/root/tests/evals"
cp "$REPO/package.json" "$F/root/package.json"
cp -R "$REPO/scripts" "$F/root/scripts"
[ -d "$REPO/src/rules" ] && cp -R "$REPO/src/rules" "$F/root/src/rules"

run() { CLAUDE_PROJECT_DIR="$F/root" bash "$G" >"$F/out.$1.txt" 2>&1; echo $?; }

# control: full copy of the real skills + agents trees
control_rc=$(run control)
cp -f "$F/root/tests/evals/results/static-analysis.json" "$F/res.control.json" 2>/dev/null

# fault: ZERO skills to analyse (empty src/skills)
rm -rf "$F/root/src/skills"; mkdir -p "$F/root/src/skills"
rm -f "$F/root/tests/evals/results/static-analysis.json"
fault_rc=$(run fault)
cp -f "$F/root/tests/evals/results/static-analysis.json" "$F/res.fault.json" 2>/dev/null

# fault2: zero skills AND zero agents
rm -rf "$F/root/src/agents"; mkdir -p "$F/root/src/agents"
rm -f "$F/root/tests/evals/results/static-analysis.json"
fault2_rc=$(run fault2)
cp -f "$F/root/tests/evals/results/static-analysis.json" "$F/res.fault2.json" 2>/dev/null

for a in control fault fault2; do
  echo "--- $a summary:"; jq -c '.summary' "$F/res.$a.json" 2>/dev/null || echo "  (no result file)"
done >&2

printf 'RESULT gate=%s control=%s fault=%s fault2=%s\n' \
  eval-static "$control_rc" "$fault_rc" "$fault2_rc"
